insert into prep_instructions (test_name, instruction) values
  ('سكر بعد الأكل (صيام 12-14 ساعة)', 'يُشترط الصيام 12 ساعة (تُقبل الحالات من 10-14 ساعة)'),
  ('منحني السكر للدم', 'تناول النشويات لمدة ثلاث أيام متتالية بحيث لا تقل الكمية اليومية عن 150 جم (رغيف عيش على الأقل)، يتم عمل المنحنى في الصباح بعد الصيام من 8-10 ساعات، لا بد من الاسترخاء (الجلوس) طوال فترة الاختبار (3 ساعات)، ومنع التدخين نهائيًا طوال فترة الاختبار'),
  ('بول للحمل', 'يُفضّل أول بول في الصباح مع الإقلال من تناول السوائل مساء اليوم السابق، إذا ظهرت النتيجة سالبة يُفضّل إجراء اختبار للحمل من الدم لأنه أكثر حساسية'),
  ('بول مزرعة', 'يُشترط غسل الأيدي والأعضاء التناسلية بالماء والصابون ثم تطهير فتحة البول بالمطهر (ديتول) والغسل مرة أخرى بالماء لإزالة أثر المطهر، ثم إفراغ أول نقط بول في دورة المياه والباقي في الكوب المعقم الذي يوفره المعمل. الامتناع عن المضاد الحيوي لمدة لا تقل عن 48 ساعة قبل إجراء التحليل، وفي حالة إرسال العينة من المنزل يُرجى وصولها للمعمل خلال ساعتين على الأكثر'),
  ('تجميع بول 24 ساعة', 'إفراغ المثانة في دورة المياه وتسجيل الوقت، ثم اجمع كل البول بعد ذلك حتى نفس الميعاد في اليوم التالي (24 ساعة) واحفظ البول في الثلاجة لحين إرساله إلى المعمل'),
  ('بول 3 أيام متتالية', 'يُشترط تجميع أول بول في الصباح، ويُفضّل إرسال كل عينة إلى المعمل في نفس اليوم'),
  ('بصاق 3 أيام متتالية', 'يُشترط تجميع أول بصاق في الصباح بعد المضمضة بالماء وقبل الأكل، ولا تُقبل عينات اللعاب، أرسل العينة منفصلة إلى المعمل في نفس اليوم، ويمكن استنشاق بخار الماء الساخن في الصباح لتسهيل إعطاء العينة'),
  ('تحاليل المني', 'يُشترط الامتناع عن الجماع أو الاحتلام لمدة لا تقل عن 3 أيام ولا تزيد عن 7 أيام، تُعطى العينة داخل المعمل ولا يُسمح بقبول عينات خارج المعمل مر عليها أكثر من 20 دقيقة'),
  ('مزرعة البراز', 'يُشترط وصول العينة إلى المعمل خلال ساعتين على الأكثر، ولا تُقبل أي عينة مرسلة في (بامبرز) الأطفال، مع الامتناع عن المضاد الحيوي لمدة لا تقل عن 48 ساعة'),
  ('براز الدم الخفي', 'يمتنع المريض لمدة 24 ساعة عن تناول جميع أنواع اللحوم أو الفجل أو أدوية الروماتيزم أو الأدوية المحتوية على الأسبرين أو فيتامين C أو الكورتيزون أو الحديد، كما لا يُسمح بأخذ المسكنات'),
  ('مسحة أمراض النساء', 'يُشترط عدم الجماع ليومين وعدم غسل المهبل لمدة 24 ساعة قبل إجراء التحليل، ويُفضّل الامتناع عن المضاد الحيوي لمدة لا تقل عن 48 ساعة'),
  ('المسحة القضيبية (البروستاتا)', 'يُشترط عدم الجماع ليومين قبل إجراء التحليل، ويُفضّل الامتناع عن المضاد الحيوي لمدة لا تقل عن 48 ساعة'),
  ('الحديد ومشتقاته', 'يُفضّل الصيام من 6-8 ساعات، والحضور بعد الانتهاء من فترة الحيض وقبل العلاج بالحديد أو نقل الدم'),
  ('CA-19.9', 'يُفضّل الصيام من 6-8 ساعات'),
  ('Cyclosporin', 'عدم تناول الموالح والوجبات الدسمة قبل التحليل، ويُفضّل أن يكون سحب العينة في نفس ميعاد الجرعة (الصباحية أو المسائية) في نفس اليوم'),
  ('G6PD', 'عدم إجراء التحليل بعد نقل دم أو حدوث انتكاسة إلا بعد مرور 3-4 أسابيع على الأقل'),
  ('Hydroxyproline', 'اجمع بول 24 ساعة في زجاجة خاصة تحتوي على حامض يستلمها المريض من المعمل، مع الامتناع عن اللحوم والجيلاتين لمدة 48 ساعة'),
  ('Catecholamine VMA', 'اجمع بول 24 ساعة في زجاجة خاصة تحتوي على حامض يستلمها المريض من المعمل، ويُشترط الامتناع لمدة لا تقل عن 72 ساعة عن تناول الشاي والقهوة والشيكولاتة والفانيليا والعرقسوس والصودا'),
  ('HIAA-5', 'اجمع بول 24 ساعة في زجاجة خاصة تحتوي على حامض يستلمها المريض من المعمل، ويُشترط الامتناع لمدة لا تقل عن 72 ساعة عن تناول الأناناس والكيوي والبرقوق والمكسرات والأفوكادو والموز والطماطم'),
  ('Aldosterone Renin', 'تناول الملح بكمية عادية لمدة 3 أيام، مع النوم والحركة بمجهود قليل لمدة ساعتين قبل تحليل (Aldosterone)، ولمدة 4 ساعات قبل تحليل (Renin)'),
  ('Postcoital Test', 'يُشترط الامتناع عن الجماع 3 أيام قبل الاختبار، والنوم على الظهر لمدة ساعتين بعد ممارسة الجماع في منتصف الدورة، وعدم التنظيف المهبلي الداخلي (سواء بالدش أو الأصابع) قبل أو بعد الجماع')
